api.neutralTraining = (function () {
  const ids = {
    warrior: ['heroicstrike', 'thunder', 'rend'],
    paladin: ['judgement', 'crusader', 'hoj'],
    druid: ['wrath', 'moonfire', 'entangle'],
    priest: ['smiteh', 'swp', 'mindblast'],
    mage: ['fireball', 'frostbolt', 'missiles'],
    hunter: ['steady', 'arcshot', 'serpent'],
    rogue: ['sinister', 'eviscerate', 'sliceanddice'],
    warlock: ['shadowbolt', 'immolate', 'corruption']
  };
  const levels = [2, 5, 9], catalog = Object.create(null);
  Object.keys(ids).forEach(function (cls) {
    if (!Object.prototype.hasOwnProperty.call(CLASSES, cls)) throw new Error('Unknown training class: ' + cls);
    catalog[cls] = Object.freeze(ids[cls].map(function (id, i) {
      if (!Object.prototype.hasOwnProperty.call(SKILLS, id)) throw new Error('Missing training skill: ' + id);
      return Object.freeze({id: id, unlockLevel: levels[i]});
    }));
  });
  function slots(cls, level) {
    if (!Object.prototype.hasOwnProperty.call(catalog, cls)) throw new Error('Unknown training class: ' + cls);
    if (!Number.isInteger(level) || level < 1 || level >= 15) throw new RangeError('Training requires own level 1..14; select a specialization kit from 15');
    return catalog[cls].map(function (row) {
      const skill = SKILLS[row.id];
      return Object.freeze({id: row.id, name: skill.name, icon: skill.icon, description: skill.text,
        unlockLevel: row.unlockLevel, source: 'training', available: level >= row.unlockLevel});
    });
  }
  function active(cls, level) { return slots(cls, level).filter(function (row) { return row.available; }).map(function (row) { return row.id; }); }
  return Object.freeze({classes: Object.freeze(Object.keys(catalog)), specLevel: 15, slots: slots, active: active});
})();
if (typeof module !== 'undefined' && module.exports) module.exports = api;
